package com.steven.assets.service.srpp.us;

import com.fasterxml.jackson.databind.node.*;
import com.steven.assets.dto.*;
import com.steven.assets.repository.*;
import com.steven.assets.service.*;
import com.steven.assets.service.srpp.PublishedSwaggerIdentity;
import com.steven.assets.service.srpp.report.SrppReportFixtures;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static com.steven.assets.service.srpp.us.UsReportFixtures.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class UsReportCaptureAdapterTest {
    @Test void positiveLegacySourceAndUnexplainedEmptyHistoryStayUnavailableInNewCapture(){
        var assets=mock(LatestAssetsService.class);when(assets.getLatestForOwner(7)).thenReturn(SrppReportFixtures.MAPPER.convertValue(assets(),LatestAssetsDto.Response.class));
        var radar=mock(TradingRadarService.class);ObjectNode list=JsonNodeFactory.instance.objectNode();list.putArray("stocks");
        when(radar.getListForOwner(7)).thenReturn(SrppReportFixtures.MAPPER.convertValue(list,TradingRadarDto.ListResponse.class));
        var prices=mock(PriceQueryService.class);var key=new PriceQueryService.PriceKey("GOOGL","美股");
        var live=new PriceQueryService.LivePrice("GOOGL","Google","美股",java.math.BigDecimal.TEN,java.math.BigDecimal.TEN,
                null,null,null,null,null,null,null,100L,DAY.toString(),AT.toString(),false,"NASDAQ","LIVE");
        when(prices.getLiveBatch(anySet(),anyMap())).thenReturn(Map.of(key,Optional.of(live)));
        var dividends=mock(StockDividendHistoryRepository.class);var swagger=mock(PublishedSwaggerIdentity.class);
        when(swagger.sha256()).thenReturn(Optional.of(SWAGGER));
        var adapter=new UsReportCaptureAdapter(assets,prices,radar,mock(StockPriceHistoryRepository.class),dividends,
                mock(TechnicalIndicatorService.class),calendar(),AUTHORITY,swagger,SrppReportFixtures.MAPPER,Clock.fixed(AT,ZoneOffset.UTC));
        for(String quality:List.of("EMPTY","LEGACY","RESOLVED")){
            when(dividends.findByStockSinceYear(eq("GOOGL"),eq("美股"),anyInt())).thenReturn(!"EMPTY".equals(quality)?List.of(
                    com.steven.assets.model.StockDividendHistory.builder().stockCode("GOOGL").market("美股")
                            .id(1L).canonicalDate(DAY.minusDays(10)).exDividendDate(DAY.minusDays(10)).sourceSnapshotId(1L)
                            .source("NASDAQ").cashDividend(java.math.BigDecimal.ONE).stockDividend(java.math.BigDecimal.ZERO)
                            .resolutionStatus(quality).build()):List.of());
            var capture=adapter.capture(7,DAY,Set.of(),null);
            var rows=capture.sources().path("market").path("symbols");
            var google=java.util.stream.StreamSupport.stream(rows.spliterator(),false).filter(n->"GOOGL".equals(n.path("stockCode").asText())).findFirst().orElseThrow();
            var distribution=google.path("quote").path("dividendHistory");
            assertThat(distribution.path("source").isNull()).isTrue();
            assertThat(distribution.path("message").asText()).isEqualTo("RESOLVED".equals(quality)
                    ?"US_DIVIDEND_PRICE_BASIS_UNVERIFIED":"CANONICAL_DIVIDEND_HISTORY_UNVERIFIED");
            assertThat(distribution.path("rows")).isEmpty();
        }
    }
    @Test void nonNullStaleOrFutureAssetsCannotSupplyMoneyOrHoldingMembership(){for(Instant generated:List.of(AT.minusSeconds(301),AT.plusSeconds(1))){ObjectNode source=assets();source.put("generatedAt",generated.toString());var f=captureWithClock(source,Clock.fixed(AT,ZoneOffset.UTC));assertThat(f.sources().path("assets").isNull()).isTrue();assertThat(f.sourceVector().path("assets").path("validation").asText()).isEqualTo("UNAVAILABLE");assertThat(f.sources().path("us-tactical").path("total_assets_twd").isNull()).isTrue();assertThat(f.sources().path("universe").path("holdingSymbols")).isEmpty();assertThat(f.sources().path("universe").path("reasonCodes")).extracting(n->n.asText()).contains("ASSETS_CURRENT_ROUND_STALE");}}
    @Test void assetsAreRecheckedAtCaptureEndAndFiveMinuteBoundaryRemainsInclusive(){for(long seconds:List.of(300L,301L)){var calls=new java.util.concurrent.atomic.AtomicInteger();Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return calls.getAndIncrement()==0?AT:AT.plusSeconds(seconds);}};var f=captureWithClock(assets(),clock);if(seconds==300){assertThat(f.sources().path("assets").isNull()).isFalse();assertThat(f.sources().path("universe").path("holdingSymbols")).extracting(n->n.asText()).containsExactly("GOOGL");}else{assertThat(f.sources().path("assets").isNull()).isTrue();assertThat(f.sourceVector().path("assets").path("coverage").asText()).isEqualTo("NONE");assertThat(f.sources().path("market").path("symbols")).isEmpty();assertThat(f.sources().path("us-tactical").path("candidates")).isEmpty();assertThat(f.sources().path("us-tactical").path("total_assets_twd").isNull()).isTrue();assertThat(f.sources().path("universe").path("symbols")).isEmpty();assertThat(f.sources().path("universe").path("reasonCodes")).extracting(n->n.asText()).contains("ASSETS_CURRENT_ROUND_STALE");}}}
    private static UsReportCapturePort.Frozen captureWithClock(ObjectNode source,Clock clock){var assets=mock(LatestAssetsService.class);when(assets.getLatestForOwner(7)).thenReturn(SrppReportFixtures.MAPPER.convertValue(source,LatestAssetsDto.Response.class));var radar=mock(TradingRadarService.class);ObjectNode list=JsonNodeFactory.instance.objectNode();list.putArray("stocks");when(radar.getListForOwner(7)).thenReturn(SrppReportFixtures.MAPPER.convertValue(list,TradingRadarDto.ListResponse.class));var prices=mock(PriceQueryService.class);when(prices.getLiveBatch(anySet(),anyMap())).thenReturn(Map.of());var history=mock(StockPriceHistoryRepository.class);when(history.findByStockCodeAndMarketAndTradingDateBetweenOrderByTradingDateAsc(any(),any(),any(),any())).thenReturn(List.of());var swagger=mock(PublishedSwaggerIdentity.class);when(swagger.sha256()).thenReturn(Optional.of(SWAGGER));var adapter=new UsReportCaptureAdapter(assets,prices,radar,history,mock(StockDividendHistoryRepository.class),mock(TechnicalIndicatorService.class),calendar(),AUTHORITY,swagger,SrppReportFixtures.MAPPER,clock);return adapter.capture(7,DAY,Set.of(),null);}
    @Test void nonNullButInvalidL0NeverRetainsAssetsMoneyOrHoldingMembership(){
        ObjectNode invalid=assets();invalid.put("generatedAt",Instant.now().toString());invalid.withObject("liveAssets").put("liveStockValue",9999);var assets=mock(LatestAssetsService.class);when(assets.getLatestForOwner(7)).thenReturn(SrppReportFixtures.MAPPER.convertValue(invalid,LatestAssetsDto.Response.class));var radar=mock(TradingRadarService.class);ObjectNode list=JsonNodeFactory.instance.objectNode();list.putArray("stocks");when(radar.getListForOwner(7)).thenReturn(SrppReportFixtures.MAPPER.convertValue(list,TradingRadarDto.ListResponse.class));var prices=mock(PriceQueryService.class);when(prices.getLiveBatch(anySet(),anyMap())).thenReturn(Map.of());var swagger=mock(PublishedSwaggerIdentity.class);when(swagger.sha256()).thenReturn(Optional.of(SWAGGER));var adapter=new UsReportCaptureAdapter(assets,prices,radar,mock(StockPriceHistoryRepository.class),mock(StockDividendHistoryRepository.class),mock(TechnicalIndicatorService.class),calendar(),AUTHORITY,swagger,SrppReportFixtures.MAPPER);var f=adapter.capture(7,DAY,Set.of(),null);
        assertThat(f.sources().path("assets").isNull()).isTrue();assertThat(f.sourceVector().path("assets").path("coverage").asText()).isEqualTo("NONE");assertThat(f.sourceVector().path("assets").path("validation").asText()).isEqualTo("UNAVAILABLE");assertThat(f.sources().path("us-tactical").path("total_assets_twd").isNull()).isTrue();assertThat(f.sources().path("universe").path("holdingSymbols")).isEmpty();assertThat(f.sources().path("universe").path("coverage").asText()).isEqualTo("PARTIAL");assertThat(f.sources().path("universe").path("reasonCodes")).extracting(n->n.asText()).contains("ASSETS_L0_SOURCE_UNAVAILABLE");
    }
    @Test void capturesFullHoldingsRadarWatchUnionAndEachDetailExactlyOnceWithoutBook(){
        var assets=mock(LatestAssetsService.class);ObjectNode direct=assets();direct.put("generatedAt",Instant.now().toString());when(assets.getLatestForOwner(7)).thenReturn(SrppReportFixtures.MAPPER.convertValue(direct,LatestAssetsDto.Response.class));var prices=mock(PriceQueryService.class);when(prices.getLiveBatch(anySet(),anyMap())).thenReturn(Map.of());var radar=mock(TradingRadarService.class);ObjectNode list=JsonNodeFactory.instance.objectNode().put("ruleVersion","SYNTHETIC").put("actionPolicyVersion","EVIDENCE_GATE_V2").put("generatedAt",AT.toString());ArrayNode stocks=list.putArray("stocks");for(String code:List.of("RADAR1","RADAR2","GOOGL"))stocks.addObject().put("stockCode",code).put("market","美股");when(radar.getListForOwner(7)).thenReturn(SrppReportFixtures.MAPPER.convertValue(list,TradingRadarDto.ListResponse.class));when(radar.getStockDetailForOwner(eq(7L),anyString(),eq("美股"))).thenThrow(new NoSuchElementException("synthetic missing source"));var history=mock(StockPriceHistoryRepository.class);when(history.findByStockCodeAndMarketAndTradingDateBetweenOrderByTradingDateAsc(any(),any(),any(),any())).thenReturn(List.of());var dividends=mock(StockDividendHistoryRepository.class);var indicators=mock(TechnicalIndicatorService.class);var swagger=mock(PublishedSwaggerIdentity.class);when(swagger.sha256()).thenReturn(Optional.of(SWAGGER));var adapter=new UsReportCaptureAdapter(assets,prices,radar,history,dividends,indicators,calendar(),AUTHORITY,swagger,SrppReportFixtures.MAPPER);
        var result=adapter.capture(7,DAY,Set.of("WATCH1"),null);assertThat(result.sources().path("universe").path("symbols")).extracting(n->n.asText()).containsExactly("GOOGL","RADAR1","RADAR2","WATCH1");assertThat(result.sources().path("market").path("symbols")).hasSize(4);assertThat(result.sources().path("us-tactical").path("candidates")).hasSize(4);for(String code:List.of("GOOGL","RADAR1","RADAR2","WATCH1"))verify(radar,times(1)).getStockDetailForOwner(7L,code,"美股");verify(radar,times(1)).getListForOwner(7);verifyNoMoreInteractions(radar);for(var row:result.sources().path("market").path("symbols"))for(String field:List.of("bidLevels","askLevels","quoteDetail"))assertThat(row.path("quote").has(field)).isFalse();
    }
    @Test void missingAssetsAndRadarCannotBeRepresentedAsCompleteEmptyUniverse(){var assets=mock(LatestAssetsService.class);when(assets.getLatestForOwner(7)).thenThrow(new NoSuchElementException("missing"));var radar=mock(TradingRadarService.class);when(radar.getListForOwner(7)).thenThrow(new NoSuchElementException("missing"));var prices=mock(PriceQueryService.class);when(prices.getLiveBatch(anySet(),anyMap())).thenReturn(Map.of());var swagger=mock(PublishedSwaggerIdentity.class);when(swagger.sha256()).thenReturn(Optional.of(SWAGGER));var adapter=new UsReportCaptureAdapter(assets,prices,radar,mock(StockPriceHistoryRepository.class),mock(StockDividendHistoryRepository.class),mock(TechnicalIndicatorService.class),calendar(),AUTHORITY,swagger,SrppReportFixtures.MAPPER);var f=adapter.capture(7,DAY,Set.of(),null);assertThat(f.sources().path("universe").path("symbols")).isEmpty();assertThat(f.sources().path("universe").path("coverage").asText()).isEqualTo("PARTIAL");assertThat(f.sources().path("universe").path("reasonCodes")).extracting(n->n.asText()).contains("ASSETS_L0_SOURCE_UNAVAILABLE","US_RADAR_LIST_SOURCE_UNAVAILABLE");assertThat(f.sourceVector().path("assets").path("validation").asText()).isEqualTo("UNAVAILABLE");assertThat(f.sourceVector().path("us-tactical").path("validation").asText()).isEqualTo("UNAVAILABLE");assertThat(f.sources().path("us-tactical").path("reasonCodes")).isNotEmpty();}
}
